 public static async Task<object> Run(){
 if(!EditorApplication.isPlaying||DungeonUi.ModalOpen)throw new Exception("Unblocked Play required");Directory.CreateDirectory("검증/플레이-사용성-v5/after");var p=PlayerController.Instance;var inv=Inventory.Instance;var input=p.GetComponent<PlayerInputReader>();var origin=p.Position;int originalHp=p.Health.Current,originalPotions=p.Potions;var carry=new Demo6.Core.Dungeon.CarryData();inv.ExportTo(carry);
 var natives=InputSystem.devices.Where(d=>d is Keyboard||d is Mouse).Select(d=>new{d,enabled=d.enabled}).ToArray();var originalSettings=InputSystem.settings;var settings=UnityEngine.Object.Instantiate(originalSettings);var originalPath=AssetDatabase.GetAssetPath(originalSettings);var reviewSettings=UnityEngine.Object.Instantiate(originalSettings);InputSystem.settings=reviewSettings;reviewSettings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;var oldK=Keyboard.current;var oldM=Mouse.current;var kb=InputSystem.AddDevice<Keyboard>("V5ReviewKeyboard");var mouse=InputSystem.AddDevice<Mouse>("V5ReviewMouse");var background=InputSystem.settings.backgroundBehavior;Action current=()=>{kb.MakeCurrent();mouse.MakeCurrent();};InputSystem.onAfterUpdate+=current;var rows=new List<object>();var drops=new List<LootDrop>();var errors=new List<string>();Application.LogCallback log=(m,st,t)=>{if(t==LogType.Error||t==LogType.Exception)errors.Add(m);};Application.logMessageReceived+=log;
 string root="검증/플레이-사용성-v5/after/"+Screen.height+"-";
