 }finally{Application.logMessageReceived-=log;InputSystem.onAfterUpdate-=current;if(DungeonUi.ModalOpen)DungeonUi.Close(DungeonUi.Modal);foreach(var d in drops)if(d)UnityEngine.Object.Destroy(d.gameObject);inv.ImportFrom(carry);p.RestoreVitals(originalHp,originalPotions);p.Teleport(origin);Camera.main.GetComponent<DungeonCamera>().Snap();InputSystem.RemoveDevice(kb);InputSystem.RemoveDevice(mouse);foreach(var d in natives)if(d.enabled)InputSystem.EnableDevice(d.d);oldK?.MakeCurrent();oldM?.MakeCurrent();InputSystem.settings.backgroundBehavior=background;InputSystem.settings=string.IsNullOrEmpty(originalPath)?settings:AssetDatabase.LoadAssetAtPath<InputSettings>(originalPath);}
